#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

# Repo-relative paths (this script lives at
# .scratch/transport-crypto-layer/verify-esp-now-relay/run-wizard.sh).
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
FEATURE_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
OUT_DIR="$SCRIPT_DIR/out"
MAC_SKETCH_SRC="$FEATURE_DIR/mac-discovery/mac-discovery.ino"
RELAY_SKETCH_SRC="$FEATURE_DIR/esp-now-relay/esp-now-relay.ino"
PORT_A="/dev/ttyACM0"
PORT_B="/dev/ttyACM1"
BAUD=115200

mkdir -p "$OUT_DIR"

# ── ESP32-specific helpers (not part of the shared library above) ────────

# _check_port_free PORT — warn (don't fail) if something already holds it.
_check_port_free() {
  local port="$1"
  if command -v fuser >/dev/null 2>&1 && fuser "$port" >/dev/null 2>&1; then
    warn "something is already holding $port:"
    fuser -v "$port" 2>&1 | sed 's/^/    /'
    warn "close Arduino IDE's Serial Monitor / any open serial connection to $port, then continue."
    pause "Press Enter once $port is free"
  else
    note "$port looks free."
  fi
}

# _read_mac PORT — open PORT at BAUD for a few seconds with python3+pyserial,
# look for a line like "MAC: AA:BB:CC:DD:EE:FF", print just the MAC on
# success. Prints nothing and returns 1 on failure (no pyserial, no line
# seen, port busy, etc.) so the caller can fall back to asking the human.
_read_mac() {
  local port="$1"
  python3 - "$port" "$BAUD" <<'PYEOF' 2>/dev/null
import re, sys, time
try:
    import serial
except ImportError:
    sys.exit(1)

port, baud = sys.argv[1], int(sys.argv[2])
try:
    ser = serial.Serial(port, baud, timeout=1)
except Exception:
    sys.exit(1)

deadline = time.time() + 6
mac_re = re.compile(r"MAC:\s*([0-9A-Fa-f:]{17})")
try:
    while time.time() < deadline:
        line = ser.readline().decode("utf-8", "ignore").strip()
        m = mac_re.search(line)
        if m:
            print(m.group(1))
            sys.exit(0)
finally:
    ser.close()
sys.exit(1)
PYEOF
}

# _discover_mac PORT VARNAME BOARD_LABEL — try the automated read, fall back
# to asking the human to copy the MAC off the Arduino Serial Monitor.
_discover_mac() {
  local port="$1" varname="$2" label="$3" mac=""
  note "Trying to read the MAC automatically from $port..."
  if mac=$(_read_mac "$port"); then
    printf '  %s✓ read%s %s MAC: %s%s%s\n' "$GREEN" "$RESET" "$label" "$BOLD" "$mac" "$RESET"
  else
    warn "couldn't read it automatically (pyserial missing, port busy, or no line seen yet)."
    say "Open the Serial Monitor in Arduino IDE for $port (115200 baud) and copy the printed MAC."
    ask mac "Paste $label's MAC address (AA:BB:CC:DD:EE:FF):"
  fi
  printf -v "$varname" '%s' "$mac"
}

# _mac_to_c_array MAC — "AA:BB:CC:DD:EE:FF" -> "0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF"
_mac_to_c_array() {
  local mac="$1"
  IFS=':' read -ra bytes <<< "$mac"
  local out=""
  for b in "${bytes[@]}"; do
    out+="0x${b}, "
  done
  printf '%s' "${out%, }"
}

# _write_relay_sketch PEER_MAC OUT_SUBDIR SKETCH_NAME — copy the real relay
# sketch into its own named sketch folder (Arduino IDE requires the .ino's
# parent directory to share its basename) with PEER_MAC filled in. Fails
# loudly (rather than silently shipping the all-zero placeholder MAC) if
# esp-now-relay.ino's PEER_MAC declaration doesn't match what this sed
# expects — e.g. because the source sketch's declaration line changed.
_write_relay_sketch() {
  local peer_mac="$1" out_subdir="$2" sketch_name="$3"
  local c_array dest_dir dest_file
  c_array=$(_mac_to_c_array "$peer_mac")
  dest_dir="$OUT_DIR/$out_subdir"
  dest_file="$dest_dir/$sketch_name.ino"
  mkdir -p "$dest_dir"
  sed -E "s/^static uint8_t PEER_MAC\[6\] = \{.*\};/static uint8_t PEER_MAC[6] = {${c_array}};/" \
    "$RELAY_SKETCH_SRC" > "$dest_file"
  if ! grep -qF "PEER_MAC[6] = {${c_array}};" "$dest_file"; then
    warn "PEER_MAC substitution didn't take in $dest_file — esp-now-relay.ino's PEER_MAC line may have changed."
    warn "Open $RELAY_SKETCH_SRC and $dest_file and fix PEER_MAC by hand before flashing."
  fi
  printf '%s' "$dest_file"
}

banner "Issue 03 — ESP32 dumb-relay firmware: MAC discovery, flash, verify"

# ── Stage 1: ports free ────────────────────────────────────────────────────
stage "Check the serial ports are free"
say "Two boards are expected at $PORT_A and $PORT_B."
say "Arduino IDE's own Serial Monitor is the usual culprit for holding a port open."
_check_port_free "$PORT_A"
_check_port_free "$PORT_B"

# ── Stage 2: discover both MACs ────────────────────────────────────────────
stage "Discover each board's ESP-NOW (WiFi) MAC address"
say "ESP-NOW addresses peers by WiFi station MAC, which is NOT the USB serial ID."
say "Sketch to flash for this step: $MAC_SKETCH_SRC"
warn "Reminder from issue 02: set Tools → USB CDC On Boot → Enabled, or nothing echoes back over $PORT_A/$PORT_B."
echo

step "In Arduino IDE: open mac-discovery.ino, select Board A's port ($PORT_A), enable USB CDC On Boot, Upload."
pause "Press Enter once Board A is flashed and running"
_discover_mac "$PORT_A" MAC_A "Board A ($PORT_A)"

step "Now select Board B's port ($PORT_B) in Arduino IDE (same sketch, still open), enable USB CDC On Boot, Upload."
pause "Press Enter once Board B is flashed and running"
_discover_mac "$PORT_B" MAC_B "Board B ($PORT_B)"

echo
note "Board A ($PORT_A) MAC: $MAC_A"
note "Board B ($PORT_B) MAC: $MAC_B"
if [[ -z "$MAC_A" || -z "$MAC_B" ]]; then
  warn "one or both MACs are empty — re-run this wizard once you have both."
  exit 1
fi

# ── Stage 3: generate the two per-board sketches ───────────────────────────
stage "Generate per-board relay firmware with the peer MAC filled in"
say "Board A's firmware needs to send to Board B's MAC, and vice versa."
RELAY_A_FILE=$(_write_relay_sketch "$MAC_B" "board-a-esp-now-relay" "board-a-esp-now-relay")
RELAY_B_FILE=$(_write_relay_sketch "$MAC_A" "board-b-esp-now-relay" "board-b-esp-now-relay")
printf '  %s✓ wrote%s %s (peer = Board B, %s)\n' "$GREEN" "$RESET" "$RELAY_A_FILE" "$MAC_B"
printf '  %s✓ wrote%s %s (peer = Board A, %s)\n' "$GREEN" "$RESET" "$RELAY_B_FILE" "$MAC_A"

# ── Stage 4: flash each board ───────────────────────────────────────────────
stage "Flash each board with its real relay firmware"
warn "Same USB CDC On Boot reminder applies here too."
step "In Arduino IDE: open $RELAY_A_FILE, select $PORT_A, Upload."
pause "Press Enter once Board A is flashed with its relay firmware"
step "In Arduino IDE: open $RELAY_B_FILE, select $PORT_B, Upload."
pause "Press Enter once Board B is flashed with its relay firmware"
_check_port_free "$PORT_A"
_check_port_free "$PORT_B"

# ── Stage 5: verify the wireless round trip ─────────────────────────────────
stage "Verify: bytes into Board A's serial arrive at Board B's serial (and back)"
VERIFY_OK=1
if python3 -c "import serial" >/dev/null 2>&1; then
  say "Running the automated two-port round-trip check..."
  if python3 "$SCRIPT_DIR/verify_round_trip.py" "$PORT_A" "$PORT_B" "$BAUD"; then
    printf '  %s✓ both directions round-tripped byte-for-byte%s\n' "$GREEN" "$RESET"
  else
    VERIFY_OK=0
    warn "automated check reported a mismatch or timeout — see output above."
  fi
else
  VERIFY_OK=0
  warn "pyserial not available — verify manually instead:"
  step "Terminal 1: stty -F $PORT_A $BAUD raw -echo && cat $PORT_A"
  step "Terminal 2: printf 'hello-from-A' > $PORT_B is wrong direction; write INTO A, read FROM B:"
  step "Terminal 2 (read B): stty -F $PORT_B $BAUD raw -echo && cat $PORT_B"
  step "Terminal 3 (write A): printf 'hello-from-A' > $PORT_A"
  say "Confirm 'hello-from-A' appears verbatim in Terminal 2, then repeat the reverse direction (write B, read A)."
  if confirm "Did bytes round-trip correctly in both directions?"; then
    VERIFY_OK=1
  fi
fi

if [[ "$VERIFY_OK" -eq 1 ]]; then
  note "Issue 03 verification: PASS — update .scratch/transport-crypto-layer/issues/03-esp32-firmware.md accordingly."
else
  SKIPPED+=("Issue 03 hardware verification did not pass — re-run this wizard's last stage after investigating.")
fi
# ──────────────────────────────────────────────────────────────────────────

finish
